<?php
declare(strict_types=1);
require_once __DIR__.'/../../../public/api/admin/ThumbnailService.php';require_once __DIR__.'/../../../public/api/admin/ThumbnailUploadService.php';require_once __DIR__.'/../../../public/api/admin/DatasetPackage.php';
use FreeTV\Admin\DatasetPackage;use FreeTV\Admin\ThumbnailUploadException;use FreeTV\Admin\ThumbnailUploadService;use PHPUnit\Framework\Attributes\DataProvider;use PHPUnit\Framework\TestCase;
final class ThumbnailUploadServiceTest extends TestCase
{
 private string $root,$source,$thumbs,$undo;private ThumbnailUploadService $service;
 protected function setUp():void{if(!extension_loaded('imagick'))self::markTestSkipped('Imagick is required for thumbnail mutation tests.');$this->root=sys_get_temp_dir().'/freetv-thumb-upload-'.bin2hex(random_bytes(8));$this->source=$this->root.'/source';$this->thumbs=$this->root.'/public/thumbs';$this->undo=$this->root.'/private/undo';foreach([$this->source,$this->thumbs,$this->undo]as$d)mkdir($d,0700,true);$this->service=new ThumbnailUploadService($this->thumbs,$this->undo);}
 protected function tearDown():void{if(isset($this->root))DatasetPackage::removeTree($this->root);}
 public function testUploadNormalizesLargeJpegAndReturnsVerifiedResult():void{$src=$this->image('large.jpg',1200,1600,'#336699');$result=$this->service->store('tt10000001',$src,filesize($src),'upload');$path=$this->thumbs.'/tt10000001.jpg';self::assertSame(1000,$result['width']);self::assertSame(1333,$result['height']);self::assertSame(filesize($path),$result['bytes']);self::assertSame(0644,fileperms($path)&0777);self::assertSame('JPEG',(new Imagick($path))->getImageFormat());self::assertStringStartsWith('/thumbs/tt10000001.jpg?v=',$result['thumbnail_url']);self::assertMatchesRegularExpression('/^[a-f0-9]{64}$/',$result['undo_token']);self::assertSame([],glob($this->thumbs.'/.thumbnail-*')?:[]);}
 public function testDuplicatePreservesBytesAndSmallReplacementIsNotUpscaled():void{$large=$this->image('large.jpg',1200,1600,'blue');$this->service->store('tt10000001',$large,filesize($large),'upload');$hash=hash_file('sha256',$this->thumbs.'/tt10000001.jpg');$this->expectError(fn()=>$this->service->store('tt10000001',$large,filesize($large),'upload'),409);self::assertSame($hash,hash_file('sha256',$this->thumbs.'/tt10000001.jpg'));$small=$this->image('small.jpg',467,668,'red');$result=$this->service->store('tt10000001',$small,filesize($small),'replace');self::assertSame([467,668],[$result['width'],$result['height']]);self::assertNotSame($hash,hash_file('sha256',$this->thumbs.'/tt10000001.jpg'));$this->expectError(fn()=>$this->service->store('tt2',$small,filesize($small),'replace'),409);}
#[DataProvider('invalidProvider')]public function testInvalidAttemptsPreserveExistingAndCleanTemps(string $case,int $status):void{$good=$this->image('good.jpg',100,200,'blue');$this->service->store('tt123',$good,filesize($good),'upload');$before=hash_file('sha256',$this->thumbs.'/tt123.jpg');$source=$good;$size=filesize($good);$imdb='tt123';$operation='replace';if($case==='png'){$png=$this->image('source.png',50,50,'red','png');$source=$this->source.'/renamed.jpg';rename($png,$source);}elseif($case==='corrupt'){ $source=$this->source.'/bad.jpg';file_put_contents($source,"\xff\xd8bad");}elseif($case==='empty')$size=0;elseif($case==='oversize')$size=ThumbnailUploadService::MAX_UPLOAD_BYTES+1;elseif($case==='imdb')$imdb='../bad';elseif($case==='operation')$operation='delete';elseif($case==='missing')$source=$this->source.'/missing.jpg';$this->expectError(fn()=>$this->service->store($imdb,$source,$size,$operation),$status);self::assertSame($before,hash_file('sha256',$this->thumbs.'/tt123.jpg'));self::assertSame([],glob($this->thumbs.'/.thumbnail-*')?:[]);}
 public static function invalidProvider():array{return ['png'=>['png',400],'corrupt'=>['corrupt',400],'empty'=>['empty',400],'oversize'=>['oversize',413],'imdb'=>['imdb',400],'operation'=>['operation',400],'missing'=>['missing',400]];}
 private function image(string $name,int $w,int $h,string $color,string $format='jpeg'):string{$path=$this->source.'/'.$name;$im=new Imagick();$im->newImage($w,$h,new ImagickPixel($color));$im->setImageFormat($format);$im->writeImage($path);$im->clear();$im->destroy();return$path;}
 private function expectError(callable $fn,int $status):void{try{$fn();self::fail('expected error');}catch(ThumbnailUploadException $e){self::assertSame($status,$e->getHttpStatus());}}
}
